@pytest.mark.parametrize("source", ["usage", "payload"]) @pytest.mark.parametrize( "field", ["total_cost_usd", "cost_usd", "cost", "base_cost_usd", "platform_fee_usd"] ) @pytest.mark.parametrize("lexeme", ["1e-1000", "-1e-1000"]) @pytest.mark.asyncio async def test_response_text_nonzero_cost_lexeme_never_becomes_free(source, field, lexeme): gateway = TextGateway(response_text(source, field, lexeme)) response = await gateway.generate(user="hello", max_tokens=1) # This actual decoder assertion distinguishes the HTTP-text boundary from dict-only probes. raw = response.raw["usage"] if source == "usage" else response.raw > assert Decimal(str(raw[field])) == Decimal(lexeme) E AssertionError: assert Decimal('0.0') == Decimal('1E-1000') E + where Decimal('0.0') = Decimal('0.0') E + where '0.0' = str(0.0) E + and Decimal('1E-1000') = Decimal('1e-1000')
